// Localiza uma ação específica dentro da resposta da Meta.
function valorAcao(acoes, tipo) {
  if (!Array.isArray(acoes)) return 0;
  const achou = acoes.find(a => a.action_type === tipo);
  return achou ? Number(achou.value) || 0 : 0;
}

// Gera uma chave estável: data + conta + nível + ID.
function chave(data, conta, nivel, id) {
  return [data, conta, nivel, id].join('|');
}

const dados = items[0].json.data || [];

return dados.map(campanha => {
  const investimento = Number(campanha.spend || 0);
  const conversas = valorAcao(campanha.actions, 'onsite_conversion.messaging_conversation_started_7d');
  const data = campanha.date_start || campanha.date_stop || '';
  const conta = campanha.account_id || '742175035567342';

  // LEADS permanece igual a conversas nesta fase para manter compatibilidade.
  const leads = conversas;

  return { json: {
    'CHAVE REGISTRO': chave(data, conta, 'campanha', campanha.campaign_id || ''),
    'DATA REFERENCIA': data,
    'CONTA ANUNCIO': conta,
    'DATA INCIO': campanha.date_start || '',
    'DATA FIM': campanha.date_stop || '',
    'NIVEL ANALISE': 'Campanha',
    'ID CAMPANHA': campanha.campaign_id || '',
    'NOME CAMPANHA': campanha.campaign_name || '',
    'OBJETIVO': campanha.objective || '',
    'OBJETIVO ORIGINAL': campanha.objective || '',
    'CONJUNTO': 'Nível Campanha',
    'ANUNCIO': 'Nível Campanha',
    'INVESTIMENTO': Number(investimento.toFixed(2)),
    'IMPRESSOES': Number(campanha.impressions || 0),
    'ALCANCE': Number(campanha.reach || 0),
    'CLIQUES': Number(campanha.clicks || 0),
    'LEADS': leads,
    'CPC': campanha.cpc ? Number(Number(campanha.cpc).toFixed(2)) : 0,
    'CTR': campanha.ctr ? Number(Number(campanha.ctr).toFixed(2)) : 0,
    'CPM': campanha.cpm ? Number(Number(campanha.cpm).toFixed(2)) : 0,
    'CPL': leads > 0 ? Number((investimento / leads).toFixed(2)) : '',
    'CLIQUES LINK': valorAcao(campanha.actions, 'link_click'),
    'CONVERSAS INICIADAS': conversas,
    'PRIMEIRAS RESPOSTAS': valorAcao(campanha.actions, 'onsite_conversion.messaging_first_reply'),
    'CONEXOES MENSAGEM': valorAcao(campanha.actions, 'onsite_conversion.total_messaging_connection'),
    'VISUALIZAÇÕES VIDEO': valorAcao(campanha.actions, 'video_view'),
    'CUSTO POR CONVERSA': conversas > 0 ? Number((investimento / conversas).toFixed(2)) : ''
  } };
});

